<?php declare(strict_types=1); require_once __DIR__.'/bootstrap.php';$r=$_SESSION['result']??null;$m=$_SESSION['meta']??[];if(!$r)redirect('index.php');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Results</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.datatables.net/2.1.8/css/dataTables.bootstrap5.css" rel="stylesheet"><link href="languages/assets/css/app.css" rel="stylesheet"><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.6/dist/chart.umd.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jquery@3.7.1/dist/jquery.min.js"></script><script src="https://cdn.datatables.net/2.1.8/js/dataTables.min.js"></script><script src="https://cdn.datatables.net/2.1.8/js/dataTables.bootstrap5.min.js"></script></head><body><aside class="sidebar"><div class="brand">Student Compare</div><a class="active" href="index.php">Compare</a><a href="history.php">History</a><a href="settings.php">Settings</a></aside><main class="content"><div class="d-flex flex-wrap justify-content-between gap-2 mb-4"><div><h2>Comparison Results</h2><small class="text-secondary"><?=e($m['file_a']??'')?> vs <?=e($m['file_b']??'')?></small></div><div><a class="btn btn-success" href="export.php?type=xlsx">Excel</a> <a class="btn btn-outline-secondary" href="export.php?type=csv">CSV</a> <button class="btn btn-outline-dark" onclick="print()">Print</button> <a class="btn btn-primary" href="index.php">New</a></div></div><div class="row g-3 mb-4"><?php foreach([['Total A',$r['totalA'],'primary'],['Total B',$r['totalB'],'secondary'],['Matched',$r['matched'],'success'],['Modified',$r['modified'],'warning'],['Missing A',$r['missingA'],'danger'],['Missing B',$r['missingB'],'danger'],['Duplicate',$r['duplicate'],'info'],['Invalid',$r['invalid'],'dark']] as $x):?><div class="col-6 col-md-3"><div class="metric border-start border-4 border-<?=$x[2]?>"><small><?=e($x[0])?></small><h3><?=e($x[1])?></h3></div></div><?php endforeach;?></div><div class="row g-4 mb-4"><div class="col-lg-5"><div class="card border-0 shadow-sm"><div class="card-body"><h5>Matching Percentage</h5><canvas id="pie"></canvas><h2 class="text-center mt-2"><?=e($r['percentage'])?>%</h2></div></div></div><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body"><h5>Status</h5><canvas id="bar"></canvas></div></div></div></div><div class="card border-0 shadow-sm"><div class="card-body table-responsive"><table id="results" class="table table-hover"><thead><tr><th>No</th><th>Student Name A</th><th>Student Name B</th><th>IC A</th><th>IC B</th><th>Student ID A</th><th>Student ID B</th><th>Status</th><th>Difference</th><th>Remarks</th></tr></thead><tbody><?php foreach($r['results'] as $i=>$x):$cls=$x['status']==='Match'?'match':($x['status']==='Modified'?'modified':'missing');?><tr class="<?=$cls?>"><td><?=$i+1?></td><td><?=e($x['nameA'])?></td><td><?=e($x['nameB'])?></td><td><?=e($x['icA'])?></td><td><?=e($x['icB'])?></td><td><?=e($x['idA'])?></td><td><?=e($x['idB'])?></td><td><?=e($x['status'])?></td><td><?=e($x['difference'])?></td><td><?=e($x['remarks'])?></td></tr><?php endforeach;?></tbody></table></div></div></main><script>new DataTable('#results',{pageLength:25});new Chart(pie,{type:'doughnut',data:{labels:['Matched','Modified','Missing'],datasets:[{data:[<?=$r['matched']?>,<?=$r['modified']?>,<?=$r['missingA']+$r['missingB']?>]}]}});new Chart(bar,{type:'bar',data:{labels:['Matched','Modified','Missing A','Missing B','Duplicate','Invalid'],datasets:[{label:'Records',data:[<?=$r['matched']?>,<?=$r['modified']?>,<?=$r['missingA']?>,<?=$r['missingB']?>,<?=$r['duplicate']?>,<?=$r['invalid']?>]}]}});</script></body></html>
